#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/shell/shell.h>
#include <zephyr/device.h>

extern const struct device *shell_device_filter(uint32_t idx, const char *filter_str);

static void shell_device_filter_test_unfiltered(void)
{
	const struct device *d0;

	/* Get the first available device using the standard API. */
	d0 = device_get_by_idx(0);

	/* The shell_device_filter with index 0 and NULL filter string
	 * should return the first available device, matching device_get_by_idx(0).
	 * If no devices are available, both should return NULL.
	 */
	zassert_equal(d0, shell_device_filter(0, NULL),
		      "d0 not equal to shell_device_filter(0, NULL)");
}

static void shell_device_filter_test_filtered_by_name(void)
{
	const struct device *dev;
	const struct device *filtered_dev;

	/* Try to find a device that is likely to exist, e.g., a console device. */
	dev = device_get_binding(CONFIG_UART_CONSOLE_ON_DEV_NAME);

	if (dev == NULL) {
		/* If console device is not available, skip this test or assert failure.
		 * For robustness, we can skip if not found.
		 */
		TC_PRINT("Console device %s not found, skipping filtered test.\n",
			 CONFIG_UART_CONSOLE_ON_DEV_NAME);
		ztest_skip();
		return;
	}

	/* Filter by the exact name of the console device. */
	filtered_dev = shell_device_filter(0, CONFIG_UART_CONSOLE_ON_DEV_NAME);

	zassert_equal(dev, filtered_dev,
		      "Filtered device by name not equal to expected device");

	/* Ensure that requesting the second device with the same filter returns NULL
	 * if only one device matches.
	 */	
	filtered_dev = shell_device_filter(1, CONFIG_UART_CONSOLE_ON_DEV_NAME);
	zassert_is_null(filtered_dev, "Second filtered device should be NULL");
}

static void shell_device_filter_test_filtered_by_nonexistent_name(void)
{
	const struct device *filtered_dev;

	/* Filter by a name that should not exist. */
	filtered_dev = shell_device_filter(0, "nonexistent_device");

	zassert_is_null(filtered_dev, "Filtered device by nonexistent name should be NULL");
}

void test_main(void)
{
	ztest_test_suite(shell_device_filter_test_suite,
			ztest_unit_test(shell_device_filter_test_unfiltered),
			ztest_unit_test(shell_device_filter_test_filtered_by_name),
			ztest_unit_test(shell_device_filter_test_filtered_by_nonexistent_name)
			);
	ztest_run_test_suite(shell_device_filter_test_suite);
}
